<?php require_once 'includes/auth.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: admin.php');exit;} $id=(int)($_POST['id']??0);$status=$_POST['status']??'Pending';$allowed=['Pending','Assigned','In Progress','Resolved'];if(!in_array($status,$allowed,true)){exit('Invalid status.');}$assigned=trim($_POST['assigned_to']??'');$note=trim($_POST['admin_note']??'');$st=$pdo->prepare('UPDATE complaints SET status=?,assigned_to=?,admin_note=? WHERE id=?');$st->execute([$status,$assigned?:null,$note?:null,$id]);header('Location: complaint.php?id='.$id.'&updated=1');exit;
